import{_ as d,C as o,o as s,c as n,a2 as t,E as a}from"./chunks/framework.Lq8Lraw_.js";const f=JSON.parse('{"title":"Git 交互演练场","description":"用可操作的图解理解三方合并与 revision 语法","frontmatter":{"title":"Git 交互演练场","description":"用可操作的图解理解三方合并与 revision 语法"},"headers":[],"relativePath":"playground/index.md","filePath":"playground/index.md","lastUpdated":1793619381000}'),l={name:"playground/index.md"};function c(_,e,p,h,u,g){const i=o("MergePlayground"),r=o("RevisionExplorer");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="git-交互演练场" tabindex="-1">Git 交互演练场 <a class="header-anchor" href="#git-交互演练场" aria-label="Permalink to &quot;Git 交互演练场&quot;">​</a></h1><p>静态文章讲原理，演练场负责把原理“动手跑一遍”。下面两个组件不依赖真实仓库，所有状态都在浏览器里计算，可以放心试错。</p><h2 id="三方合并-冲突到底是怎么判出来的" tabindex="-1">三方合并：冲突到底是怎么判出来的 <a class="header-anchor" href="#三方合并-冲突到底是怎么判出来的" aria-label="Permalink to &quot;三方合并：冲突到底是怎么判出来的&quot;">​</a></h2><p>先看三个版本：共同祖先 <code>base</code>、当前分支 <code>ours</code>、被合并分支 <code>theirs</code>。逐行比较后，只有「双方都改且改得不一样」的行才会冲突。</p>',4)),a(i),e[1]||(e[1]=t('<p>试试只解决一处冲突，观察结果区里的冲突标记如何从两处减少到一处；再点击「重置场景」回到初始状态。</p><div class="tip custom-block"><p class="custom-block-title">和命令行对照</p><p>真实仓库里，<code>git merge feature</code> 停下后可以用 <code>git ls-files -u</code> 看到 stage 1/2/3，对应这里的 base / ours / theirs。解决后 <code>git add</code> 会把三个 stage 折叠成 stage 0。</p></div><h2 id="revision-语法-一个表达式落在哪个提交" tabindex="-1">revision 语法：一个表达式落在哪个提交 <a class="header-anchor" href="#revision-语法-一个表达式落在哪个提交" aria-label="Permalink to &quot;revision 语法：一个表达式落在哪个提交&quot;">​</a></h2><p>提交图是静态的，表达式是“寻址规则”。点击下面的表达式，看它命中哪些提交，以及为什么。</p>',4)),a(r),e[2]||(e[2]=t('<p>重点区分三组容易混淆的写法：</p><table tabindex="0"><thead><tr><th>写法</th><th>含义</th><th>常见误用</th></tr></thead><tbody><tr><td><code>~2</code></td><td>沿第一父提交走两步</td><td>以为能跨 merge 的第二个父提交</td></tr><tr><td><code>^2</code></td><td>取 merge commit 的第二个父提交</td><td>对普通提交使用，直接报错</td></tr><tr><td><code>@{1}</code></td><td>引用上一次移动前的位置</td><td>当成固定提交哈希来写脚本</td></tr></tbody></table><h2 id="建议的练习顺序" tabindex="-1">建议的练习顺序 <a class="header-anchor" href="#建议的练习顺序" aria-label="Permalink to &quot;建议的练习顺序&quot;">​</a></h2><ol><li>先在 <a href="/git-tutorial-site/guide/collaboration/02-conflict-essence">冲突的本质</a> 理解三方合并模型，再回到这里动手。</li><li>读完 <a href="/git-tutorial-site/guide/internals/02-refs-and-revisions">引用体系与 revision 语法</a> 后，用上面的表达式逐个对照提交图。</li><li>读完 <a href="/git-tutorial-site/guide/internals/03-index-and-three-trees">索引与三棵树</a> 后，把冲突区的 base/ours/theirs 与 <code>git ls-files -u</code> 的 stage 编号对应起来。</li></ol>',4))])}const b=d(l,[["render",c]]);export{f as __pageData,b as default};
